/// v24.2.0 (CIRISPersist#564 stage 1) — the families whose CI axis implies
/// **routing / storage / consent / trust**, and which therefore MUST declare a
/// load-bearing predicate.
///
/// Derived IN CODE from two facts the vendored manifest already carries (rule
/// #9 — the truth lives in one place; a copied trigger column would drift):
///
/// - `affects_routing == true` — the manifest's own routing flag. Exactly
///   `consent:*` / `trace:*` / `trust:*`, which is also the storage/trust
///   surface: what we route is what we retain, and `trust:*` is the trust
///   plane itself.
/// - `round2.ci_axes.transmission_principle.usage == "family_specific"` — the
///   CI axis that IS the consent norm. A family that defines its own
///   transmission principle is a family whose objects authorize a flow.
///
/// **This bounds the GATE's discipline, not the safety property.** At runtime
/// every family with no declared predicate — inside this set or outside it —
/// resolves
/// [`Unknown`](crate::federation::load_bearing::LoadBearing::Unknown) and is
/// never released. So a trigger set that is too narrow costs coverage
/// pressure, never a wrong release; there is no reading of it that collects a
/// live object.
pub fn load_bearing_trigger_families() -> Vec<&'static str> {
    let mut out: Vec<&'static str> = Vec::new();
    let Some(obj) = families().as_object() else {
        return out;
    };
    for (prefix, fam) in obj {
        let routing = fam
            .get("affects_routing")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false);
        let consent = fam
            .get("round2")
            .and_then(|r| r.get("ci_axes"))
            .and_then(|a| a.get("transmission_principle"))
            .and_then(|t| t.get("usage"))
            .and_then(serde_json::Value::as_str)
            == Some("family_specific");
        if routing || consent {
            // The manifest is `'static` behind a `OnceLock`, so the key
            // borrows for the program's life.
            out.push(prefix.as_str());
        }
    }
    out.sort_unstable();
    out.dedup();
    out
}

/// The declared load-bearing predicate for `family_prefix` — `(kind,
/// rationale)` — or `None` for a family with no declaration at all.
///
/// `None` and `Some(("undeclared", …))` both resolve
/// [`Unknown`](crate::federation::load_bearing::LoadBearing::Unknown) at
/// runtime; they differ only in whether the gap is RECORDED. That difference is
/// the whole point of the gate: a recorded gap is reviewable, an unrecorded one
/// is a silent licence to collect.
pub fn load_bearing_predicate(family_prefix: &str) -> Option<(&'static str, &'static str)> {
    PERSIST_AUTHORED_LOAD_BEARING_PREDICATES
        .iter()
        .find(|(f, _, _)| *f == family_prefix)
        .map(|(_, kind, rationale)| (*kind, *rationale))
}

/// Every family prefix the vendored manifest declares, sorted. The universe
/// [`crate::federation::load_bearing`] resolves a dimension against.
pub fn family_prefixes() -> Vec<&'static str> {
    let mut out: Vec<&'static str> = families()
        .as_object()
        .map(|o| o.keys().map(String::as_str).collect())
        .unwrap_or_default();
    out.sort_unstable();
    out
}

/// The `families` section (per-family CI-axis assignments live under
/// `families.<prefix>.round2.ci_axes.<axis>.wire_fields`). Raw
/// [`serde_json::Value`] — this module stays the single parse point for the
/// vendored manifest; [`field_ci_axes_map`], [`load_bearing_trigger_families`]
/// and [`family_prefixes`] are its only consumers.
fn families() -> &'static serde_json::Value {
    root()
        .get("families")
        .expect("namespace_supersets.json carries a top-level families section")
}

/// The bare wire-field name from an annotated `wire_fields` entry, e.g.
/// `"cohort_scope (Global/federation-wide only)"` → `"cohort_scope"`,
/// `"ThresholdSignature[]{member_id,...}"` → `"ThresholdSignature"`. Returns
/// `""` for an entry that does not start with an identifier.
fn bare_wire_field(s: &str) -> &str {
    let s = s.trim_start();
    let end = s
        .find(|c: char| !(c.is_ascii_alphanumeric() || c == '_'))
        .unwrap_or(s.len());
    &s[..end]
}

/// v21.13.0 (CIRISPersist#532) — the DERIVED join: `field name → the set of CI
/// axes it serves`, read out of every family's
/// `round2.ci_axes.<axis>.wire_fields`. A field mapping to more than one axis
/// is the fusion signal the gate classifies. Built once; the map borrows
/// `'static` axis names from [`CI_AXES`] so callers get cheap `&'static str`s.
fn field_ci_axes_map(
) -> &'static std::collections::BTreeMap<String, std::collections::BTreeSet<&'static str>> {
    static MAP: OnceLock<
        std::collections::BTreeMap<String, std::collections::BTreeSet<&'static str>>,
    > = OnceLock::new();
    MAP.get_or_init(|| {
        let mut map: std::collections::BTreeMap<String, std::collections::BTreeSet<&'static str>> =
            std::collections::BTreeMap::new();
        let fams = families();
        let Some(obj) = fams.as_object() else {
            return map;
        };
        for fam in obj.values() {
            let Some(ci_axes) = fam.get("round2").and_then(|r| r.get("ci_axes")) else {
                continue;
            };
            let Some(axes_obj) = ci_axes.as_object() else {
                continue;
            };
            for (axis_key, entry) in axes_obj {
                // Resolve the axis key to its `'static` spelling in CI_AXES so
                // the returned sets carry no owned strings.
                let Some(&axis) = CI_AXES.iter().find(|a| **a == axis_key.as_str()) else {
                    // An unknown axis key is caught by
                    // `ci_axis_vocabulary_is_closed`; skip it here.
                    continue;
                };
                let Some(wfs) = entry.get("wire_fields").and_then(|w| w.as_array()) else {
                    continue;
                };
                for wf in wfs {
                    let Some(wf) = wf.as_str() else { continue };
                    let name = bare_wire_field(wf);
                    if name.is_empty() {
                        continue;
                    }
                    map.entry(name.to_string()).or_default().insert(axis);
                }
            }
        }
        map
    })
}

/// The set of CI axes a placement `field` serves, derived from the manifest's
/// per-family `ci_axes.wire_fields` (CIRISPersist#532). Empty for a field that
/// names no CI axis (pure `content` payload). More than one axis is the
/// fusion signal [`tests::every_multi_axis_field_is_classified`] gates.
pub fn ci_axes_for_field(field: &str) -> std::collections::BTreeSet<&'static str> {
    field_ci_axes_map().get(field).cloned().unwrap_or_default()
}

/// The fusion classification for the `(field, op)` pair — the classification
/// unit CC 4.5.1.1 (rc3) ratifies. `op` is the emitting operation's signed
/// discriminator (the row's `attestation_type`).
///
/// Resolution order:
///
/// 1. the vendored manifest's `asymmetry_kind`+note when the walk set one. The
///    vendored matrix has **no `op` column**, so a manifest classification is
///    necessarily op-invariant — it answers for every op, which is the shape of
///    the standing CC ask this module records;
/// 2. else persist's [`PERSIST_AUTHORED_AXIS_CLASSIFICATIONS`] row for exactly
///    this `(field, op)`;
/// 3. else the field's op-invariant ([`AXIS_OP_EVERY`]) row, if it has one;
/// 4. else `None` — either an UNCLASSIFIED cross-axis field (a build failure
///    under the fusion gate) or a reading that is **not admitted** under this
///    op at all (see [`PERSIST_NOT_ADMITTED_AXIS_READINGS`]; the pointer's
///    subject-binding arm is the ratified case).
///
/// Returns `(kind, rationale)`.
pub fn fusion_classification(field: &str, op: &str) -> Option<(&'static str, &'static str)> {
    // Manifest first (the authored Registry-of-Record wins over persist's proposal).
    if let Some(row) = field_processor_matrix().iter().find(|r| r.field == field) {
        if !row.asymmetry_kind.trim().is_empty() {
            // Return the `'static` spelling from ASYMMETRY_KINDS for the kind;
            // the note is borrowed from the parsed manifest ('static via OnceLock).
            let kind = ASYMMETRY_KINDS
                .iter()
                .find(|k| **k == row.asymmetry_kind.as_str())
                .copied()
                .unwrap_or("logical_defect");
            return Some((kind, row.asymmetry_note.as_str()));
        }
    }
    PERSIST_AUTHORED_AXIS_CLASSIFICATIONS
        .iter()
        .find(|(f, o, _, _)| *f == field && (*o == op || *o == AXIS_OP_EVERY))
        .map(|(_, _, kind, note)| (*kind, *note))
}

/// Is a processor permitted to read `field` as CI axis `axis` at all?
///
/// `false` iff [`PERSIST_NOT_ADMITTED_AXIS_READINGS`] forbids the pair — the
/// rc3 ruling that `references_attestation_id` never establishes
/// `data_subject`. Returns the refusal rationale alongside, so a caller that
/// hits the wall can quote the ruling rather than restate it.
pub fn not_admitted_axis_reading(field: &str, axis: &str) -> Option<&'static str> {
    PERSIST_NOT_ADMITTED_AXIS_READINGS
        .iter()
        .find(|(f, a, _)| *f == field && *a == axis)
        .map(|(_, _, why)| *why)
}

// ─────────────────────────────────────────────────────────────────────────
// CIRISPersist#586 — THE ABSENCE WITNESS.
//
// A PRESENCE claim breaks its own build when the symbol moves:
// `evidence_cc_impl_pointers_resolve` proves that on every run. An ABSENCE
// claim — "X does not exist" — is true when written and nothing ever re-asks.
// It is the only kind of claim in this manifest that rots while nobody touches
// it, and by the time CIRISPersist#586 was filed FOUR had rotted:
//
//   `wa_adjudication_ref` has NO wire path    — false since v21.8.0, doubly so after #578
//   `capacity_assurance:` has no registry row  — false since CC 1.0-rc3, closed by #590
//   the CC generator walks only `### 3.1.N`    — fixed upstream; CC 3.1.7 R2 now forbids it
//   three gated families are uncatalogued      — TRUE, and the manifest cannot say it
//
// Two of those already have witnesses, both built for other reasons and both
// of the same shape — declare the absence in a const, and fail when it ends:
// [`STILL_UNREGISTERED_COVERAGE_GAP`] (CIRISPersist#590) and
// `UNREGISTERED_GATED_FAMILIES`' liveness twin. What was missing is the
// GENERAL case: an enumeration that finds the NEXT absence claim without
// anybody remembering to write a const for it.
//
// ## What can honestly be checked, and what cannot
//
// Only STRUCTURED absence claims. The manifest states absence three ways:
//
// 1. **Structured, and already witnessed** — `registry_coverage_gap.prefixes`
//    ("these families carry no registry row"), gated by
//    [`STILL_UNREGISTERED_COVERAGE_GAP`]; and a `field_processor_matrix` row
//    whose `owner_component` or `processor` is the literal `UNASSIGNED` ("no
//    component processes this field anywhere"), gated by
//    [`KNOWN_UNASSIGNED_FIELDS`]. Note the second is much narrower than the
//    185 rows the walk marks `status: "unassigned"` — that softer flag means
//    "no LIVE processor for this field", and what makes it true is prose in
//    the `proposed:` note, so it lands in category 3 below.
// 2. **Structured, and witnessed HERE** — an object carrying
//    `asymmetry_kind: "logical_defect"` together with a `missing_dual` key.
//    `missing_dual` IS the absence marker: the object's whole content is
//    "operation X on family F has no dual Y". Nine such objects in the 0.3.0
//    cut, and the flagship rot (`ownership:*` / WA-adjudicated reclaim) is one
//    of them.
// 3. **Prose, and NOT checkable** — `primitive_gap_report`'s free-text lines,
//    `invariant_registry` `primitive_constraint` narration, and the
//    `processor` field's `proposed: …` design notes.
//
// Category 3 is where the temptation lives, and it must be refused. The
// obvious move — treat every `proposed:`-prefixed processor citation naming a
// `path#symbol` as "this symbol does not exist" — was tried and is WRONG:
// of the 56 such citations that resolve to a repo-local file, **29 name a
// symbol that exists on purpose**, because `proposed:` means "does not process
// this field yet", not "does not exist". Separating
// `proposed: admission.rs#check_reserved_prefix_admission — add a
// health:liveness: arm` (extend an existing symbol) from
// `proposed: admission.rs#reject_non_self_replication_grant (no existing
// admission check found)` (a symbol that is genuinely absent) requires reading
// the parenthetical. **Inferring a rule from a description field is the
// section-walk heuristic CC 3.1.7 R2 forbids, pointed at a different field.**
// A narrow gate that fires beats a broad one that cannot.
//
// ## The shape
//
// [`manifest_absence_claims`] DERIVES the claim set by walking the whole
// document for the structural marker — never by naming a section, so a
// re-vendor that moves `duality_audit` elsewhere still finds them. Persist
// then declares, per claim, the symbols whose existence contradicts it
// ([`PERSIST_AUTHORED_ABSENCE_FALSIFIERS`]), and
// [`tests::manifest_absence_claims_still_hold`] resolves those symbols with
// the SAME definition predicate `evidence_cc_impl_pointers_resolve` uses. The
// two are exact inverses over one predicate: presence claims must resolve,
// absence claims must not.
// ─────────────────────────────────────────────────────────────────────────

/// One **structured absence claim** derived from the vendored manifest: an
/// object the walk classified `logical_defect` whose content is a missing dual.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub struct AbsenceClaim {
    /// `"{family}|{operation}"` — the stable key
    /// [`PERSIST_AUTHORED_ABSENCE_FALSIFIERS`] is indexed by. Derived from the
    /// claim's own content, so it survives the object moving in the document.
    pub key: String,
    /// The CC 3.1 family prefix the claim is about (`"ownership:*"`).
    pub family: String,
    /// The operation whose dual is missing (`"ownership bind"`).
    pub operation: String,
    /// What the manifest says does not exist (`"WA-adjudicated reclaim"`).
    pub missing_dual: String,
}

/// The closed status vocabulary for a declared absence claim.
///
/// - `holds` — no declared falsifier resolves in persist's sources. The claim
///   is still true as far as this repo can see.
/// - `falsified` — at least one does. **The manifest is wrong on `main`**, and
///   the entry is the correction owed at the next re-vendor — the same
///   discipline `tests::DELETED_PENDING_REVENDOR` runs for a deleted citation.
///
/// Gated closed by [`tests::absence_claim_status_vocabulary_is_closed`].
pub const ABSENCE_CLAIM_STATUSES: &[&str] = &["holds", "falsified"];

